def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive_opponents = []
    prev_bids = []
    strong_bids = []
    desperate_count = 0

    for opp_id in opponents_status:
        opp = opponents_status[opp_id]
        if opp.get('alive'):
            alive_opponents.append(opp)
            if opp.get('hp', 0) <= 3 or opp.get('no_water_days', 0) >= 1:
                desperate_count += 1
            prev = opp.get('previous_trace', {})
            if prev:
                bid = prev.get('bid')
                if bid is not None:
                    prev_bids.append(float(bid))
                    if float(bid) >= 90:
                        strong_bids.append(float(bid))

    units = int(supply // WATER_REQ)
    scarcity = 0
    if units <= 1:
        scarcity = 2
    elif units == 2:
        scarcity = 1

    if not alive_opponents:
        base = 18.0
        if hp <= 2 or no_water_days >= 1:
            base = 35.0
        return float(max(0.0, min(budget, base)))

    high_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0
    top_anchor = max(strong_bids) if strong_bids else high_prev

    bid = 0.0

    if hp <= 2 or no_water_days >= 2:
        if scarcity == 2:
            bid = max(108.0, top_anchor + 2.0)
        elif scarcity == 1:
            bid = max(96.0, avg_prev + 4.0)
        else:
            bid = max(78.0, avg_prev)
    elif hp <= 4 or no_water_days >= 1:
        if scarcity == 2:
            bid = max(101.0, top_anchor + 1.0)
        elif scarcity == 1:
            bid = max(88.0, avg_prev + 2.0)
        else:
            bid = max(58.0, avg_prev * 0.75)
    else:
        if scarcity == 2:
            bid = max(94.0, top_anchor)
        elif scarcity == 1:
            bid = max(62.0, avg_prev * 0.7)
        else:
            bid = 24.0

    if desperate_count >= 2:
        bid += 6.0
    elif desperate_count == 1:
        bid += 3.0

    if day >= 8:
        bid += 4.0

    if budget < bid:
        if hp <= 3 or no_water_days >= 1:
            bid = budget
        else:
            bid = min(budget, bid * 0.85)

    if hp >= 7 and no_water_days == 0 and scarcity == 0 and high_prev >= 95:
        bid = min(bid, 20.0)

    bid = max(0.0, min(float(budget), float(bid)))
    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    # Determine alive opponents
    alive_opp = {aid: o for aid, o in opponents_status.items() if o['alive']}
    if not alive_opp:
        return min(my_status['budget'], DAILY_SALARY * 0.4)

    # Get yesterday's bids from opponents
    prev_bids = []
    for opp in alive_opp.values():
        trace = opp.get('previous_trace', {})
        if trace and trace.get('bid') is not None:
            prev_bids.append(trace['bid'])

    # Determine highest opponent bid from yesterday
    highest_prev = max(prev_bids) if prev_bids else 0

    # Determine my situation
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    # If I'm very low on HP, need water urgently
    if hp <= 2 or no_water_days >= 1:
        # Bid above highest opponent bid if possible, else max budget
        target = max(highest_prev + 1, DAILY_SALARY * 0.9)
        return min(budget, target)
    # If opponents were very aggressive yesterday, conserve if I have enough HP
    if highest_prev >= DAILY_SALARY * 0.85:
        if hp > 5:
            return min(budget, DAILY_SALARY * 0.4)
        else:
            # Moderate bid to stay competitive
            return min(budget, max(DAILY_SALARY * 0.5, highest_prev + 0.5))
    # Default: moderate bid
    return min(budget, DAILY_SALARY * 0.6)

def get_bid(day_context, my_status, opponents_status):
    DAILY_SALARY = 140
    WATER_REQ = 8
    supply = day_context['supply']
    cindy = opponents_status.get('Cindy', {})

    # Check if Cindy is alive and active
    if cindy.get('alive'):
        prev = cindy.get('previous_trace', {})
        last_bid = prev.get('bid', 0) if prev else 90

        # If supply is tight, bid to beat Cindy or at least secure water
        if supply < 18:
            bid = min(my_status['budget'], last_bid + 5.0)
        else:
            # If supply is generous, bid moderately
            bid = min(my_status['budget'], max(50.0, last_bid * 0.8))
    else:
        # If no competition, bid conservatively
        bid = min(my_status['budget'], 40.0)

    # Emergency survival
    if my_status['hp'] < 3:
        bid = min(my_status['budget'], DAILY_SALARY * 0.95)

    return float(max(0, bid))
